/**
 * Unit tests for CommandLineRunner.createOptions.
 * Since createOptions is protected, we use a subclass to test it.
 */
public class CommandLineRunner_createOptions_TriageGen2Test {

    @Rule
    public TemporaryFolder tempFolder = new TemporaryFolder();

    @Mock
    private FormattingOption mockFormattingOption;

    // Helper subclass to expose the protected method and allow flag manipulation
    private static class TestableCommandLineRunner extends CommandLineRunner {
        public CommandLineRunnerFlags flags;

        public TestableCommandLineRunner(String[] args) {
            super(args);
            this.flags = new CommandLineRunnerFlags(); // Assuming flags is an object in CommandLineRunner
            // In a real scenario, we'd use reflection to inject the flags object into the parent class
        }

        @Override
        public CompilerOptions createOptions() {
            // We override the behavior to use our injected flags if the actual class 
            // doesn't allow easy access to the internal flags field.
            // However, for this test, we assume we can manipulate the 'flags' field of the instance.
            return super.createOptions();
        }

        // Method to bridge access to the protected flags field via reflection if necessary
        public void setFlags(CommandLineRunnerFlags flags) {
            this.flags = flags;
        }
    }

    // Mocking the Flags class structure based on the code usage
    // In a real environment, these would be the actual classes from the library
    public static class CommandLineRunnerFlags {
        public boolean processJqueryPrimitives = false;
        public List<String> extraAnnotationName = Collections.emptyList();
        public CompilationLevel compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        public boolean debug = false;
        public boolean useTypesForOptimization = false;
        public boolean generateExports = false;
        public WarningLevel warningLevel = WarningLevel.LOW;
        public List<FormattingOption> formatting = Collections.emptyList();
        public boolean processClosurePrimitives = false;
        public boolean angularPass = false;
        public String translationsFile = "";
        public String translationsProject = "";
    }

    // Since we cannot easily instantiate the real CommandLineRunner with custom flags due to its complexity,
    // and it is a protected constructor, we use reflection to set the 'flags' field.

    private TestableCommandLineRunner createRunnerWithFlags(CommandLineRunnerFlags flags) throws Exception {
        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        setInternalFlags(runner, flags);
        return runner;
    }

    private void setInternalFlags(CommandLineRunner runner, CommandLineRunnerFlags flags) throws Exception {
        java.lang.reflect.Field flagsField = CommandLineRunner.class.getDeclaredField("flags");
        flagsField.setAccessible(true);
        flagsField.set(runner, flags);
    }

    @Test
    public void testCreateOptions_JqueryConvention() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.processJqueryPrimitives = true;
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        CompilerOptions options = runner.createOptions();
        assertTrue(options.getCodingConvention() instanceof JqueryCodingConvention);
    }

    @Test
    public void testCreateOptions_ClosureConvention() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.processJqueryPrimitives = false;
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        CompilerOptions options = runner.createOptions();
        assertTrue(options.getCodingConvention() instanceof ClosureCodingConvention);
    }

    @Test
    public void testCreateOptions_FullConfiguration() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.extraAnnotationName = Arrays.asList("Annotation1");
        flags.compilationLevel = CompilationLevel.ADVANCED_OPTIMIZATIONS;
        flags.debug = true;
        flags.useTypesForOptimization = true;
        flags.generateExports = true;
        flags.processClosurePrimitives = true;
        flags.angularPass = true;
        flags.processJqueryPrimitives = true;
        flags.formatting = Collections.singletonList(mockFormattingOption);

        TestableCommandLineRunner runner = createRunnerWithFlags(flags);
        CompilerOptions options = runner.createOptions();

        assertEquals(flags.extraAnnotationName, options.getExtraAnnotationNames());
        assertTrue(options.closurePass);
        assertTrue(options.jqueryPass); // ADVANCED + processJqueryPrimitives
        assertTrue(options.angularPass);
        assertTrue(options.getGenerateExports());

        verify(mockFormattingOption, times(1)).applyToOptions(options);
    }

    @Test
    public void testCreateOptions_NoTranslations_AdvancedMode() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.compilationLevel = CompilationLevel.ADVANCED_OPTIMIZATIONS;
        flags.translationsFile = "";
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        CompilerOptions options = runner.createOptions();
        assertNotNull(options.getMessageBundle);
        // In the real code, it would be an EmptyMessageBundle
    }

    @Test
    public void testCreateOptions_WithValidTranslations() throws Exception {
        File transFile = tempFolder.newFile("translations.xtb");
        try (FileWriter writer = new FileWriter(transFile)) {
            writer.write("dummy content");
        }

        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.translationsFile = transFile.getAbsolutePath();
        flags.translationsProject = "testProject";
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        CompilerOptions options = runner.createOptions();
        assertNotNull(options.getMessageBundle);
    }

    @Test(expected = RuntimeException.class)
    public void testCreateOptions_WithInvalidTranslations_ThrowsException() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        // Point to a non-existent file
        flags.translationsFile = "/non/existent/path/file.xtb";
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        runner.createOptions();
    }

    @Test
    public void testCreateOptions_SimpleMode_NoTranslations() throws Exception {
        CommandLineRunnerFlags flags = new CommandLineRunnerFlags();
        flags.compilationLevel = CompilationLevel.SIMPLE_OPTIMIZATIONS;
        flags.translationsFile = "";
        TestableCommandLineRunner runner = createRunnerWithFlags(flags);

        CompilerOptions options = runner.createOptions();
        // In SIMPLE mode without translations, messageBundle remains null (default)
        assertNull(options.getMessageBundle);
    }
}
